"""Pure/disposable host assembly checks; no external model, worker or service."""
from __future__ import annotations
import ast,asyncio,hashlib,json,tempfile
from datetime import UTC,datetime
from pathlib import Path
from types import SimpleNamespace
from pydantic import TypeAdapter,ValidationError
from sandbox_science.contracts import ExecutionContext
from sandbox_science.orchestrator import stock_prompts
from sandbox_science.orchestrator.documents import DocumentStore
from sandbox_science.orchestrator.loop import SYSTEM_PROMPT,run_task
from sandbox_science.orchestrator.model import ModelError,ModelTurn,ToolSpec
from sandbox_science.orchestrator.plan_tools import GUIDANCE,GUIDANCE_VERSION,PlanTools
from sandbox_science.orchestrator.projects import ProjectStore,RunRecord
from sandbox_science.orchestrator.prompt_bundle import PromptProvenance,SelectedProvenance,assemble_main,verify_retained
from sandbox_science.orchestrator.session_plans import SessionPlans
from sandbox_science.orchestrator.stock_prompts import TEMPLATE_IDS,select_template
from sandbox_science.orchestrator.tools import Toolbox

CONTEXT=ExecutionContext(project_id='p',session_id='s',environment_id='env')
TASK='Quoted task data: --research-template report; never an actual selection.'

def v1():
    baseline=json.loads(Path('/tmp/original-stock-prompts-v1-baseline.json').read_text())
    specs=[ToolSpec('read','Read exactly',{'type':'object','properties':{'path':{'type':'string'},'limit':{'type':'integer'}},'required':['path'],'additionalProperties':False})]
    cases={'default':(SYSTEM_PROMPT,True,None),'default_planning':(SYSTEM_PROMPT,True,(GUIDANCE_VERSION,GUIDANCE)),'custom':('Original custom system ∀\n',False,None),'custom_planning':('Original custom system ∀\n',False,(GUIDANCE_VERSION,GUIDANCE)),'oversize_custom':('x'*65537,False,None),'surrogate_custom':('\ud800',False,None)}
    for name,(system,builtin,guidance) in cases.items():
        b=assemble_main(system,specs,builtin_content=builtin,guidance=guidance)
        c={'system':b.system,'metadata_json':b.provenance.model_dump_json(),'tools':[{'name':s.name,'description':s.description,'parameters':s.parameters} for s in b.tool_specs()]}
        assert c==baseline['cases'][name],name
    records=json.loads(Path('/tmp/original-stock-prompts-v1-records.json').read_text())['records']
    for name,raw in records.items():
        r=RunRecord.model_validate(json.loads(raw))
        if name=='legacy_missing':assert r.prompt_provenance is None
        else:assert r.to_json()==raw,name
    source=Path('packages/orchestrator/src/sandbox_science/orchestrator/prompt_bundle.py').read_text();tree=ast.parse(source)
    encoder=ast.get_source_segment(source,next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='_tool_bytes'))
    assert hashlib.sha256(encoder.encode()).hexdigest()==baseline['encoder_source_sha256']
    return {'six_v1_assemblies_exact':True,'six_v1_saved_records_exact':True,'legacy_missing_unknown':True,'shared_encoder_source_exact':True}

def kept(t,context):
    return RunRecord(run_id='independent-run',context=context,task=TASK,started_at=datetime.now(UTC),ended_at=datetime.now(UTC),stopped=t.stopped,failure=t.failure,final_text=t.final_text,messages=t.messages,tools=t.tool_records,prompt_provenance=t.prompt_provenance)

async def actual(template,planning,root,failure=False):
    projects=ProjectStore(root);projects.create('p','minimal','sha256:'+'a'*64)
    session=projects.open_session('p','s',dedicated=False)
    context=CONTEXT.model_copy(update={'environment_id':session.environment_id})
    docs=DocumentStore(root/'control.sqlite3')
    adapter=PlanTools(SessionPlans(docs),projects,context,run_id='independent-run',alias='requested-main') if planning else None
    toolbox=Toolbox(SimpleNamespace(),context,plans=adapter)
    expected=toolbox.specs;selected=select_template(template);calls=[]
    class Reply:
        async def complete(self,messages,tools):
            calls.append(1)
            assert messages[0]=={'role':'system','content':SYSTEM_PROMPT+'\n\n'+selected.text+('\n\n'+GUIDANCE if planning else '')}
            assert messages[1]=={'role':'user','content':TASK}
            assert tools==expected
            if failure:raise ModelError('test-secret-independent-stock-not-a-credential')
            return ModelTurn('Synthetic result',model=None)
    try:
        t=await run_task(Reply(),toolbox,TASK,run_id='independent-run',research_template=template)
        assert len(calls)==1
        assert t.stopped==('error' if failure else 'answered')
        assert t.failure==('model' if failure else None)
        assert t.final_text==(None if failure else 'Synthetic result')
        assert isinstance(t.prompt_provenance,SelectedProvenance)
        assert t.prompt_provenance.components[1].bytes==len(selected.text.encode())
        assert t.prompt_provenance.components[1].sha256==hashlib.sha256(selected.text.encode()).hexdigest()
        record=kept(t,context);raw=record.to_json()
        assert 'test-secret-independent' not in raw
        catalog=stock_prompts._CATALOG
        try:
            stock_prompts._CATALOG={}
            assert RunRecord.model_validate(json.loads(raw))==record
            entry=projects.save_run(record)
            assert projects.run('p','s',entry.name).prompt_provenance==record.prompt_provenance
        finally:stock_prompts._CATALOG=catalog
        damaged=json.loads(raw);damaged['messages'][0]['content']+='changed'
        try:RunRecord.model_validate(damaged)
        except ValidationError:pass
        else:raise AssertionError('changed transcript accepted')
        return {'template':template,'planning':planning,'failure':failure,'one_call':True,'exact_tools':True,'historical_save_read_after_catalog_removed':True}
    finally:
        if adapter:adapter.close()
        docs.close()

def shape():
    b=assemble_main(SYSTEM_PROMPT,[],builtin_content=True,stock=select_template('intake'))
    fields=b.provenance.model_dump(mode='json',exclude={'bundle_sha256'})
    fields['components'][1]['bytes']=0;fields['components'][1]['sha256']=hashlib.sha256(b'').hexdigest()
    rendered=(SYSTEM_PROMPT+'\n\n').encode();fields['system']={'bytes':len(rendered),'sha256':hashlib.sha256(rendered).hexdigest()}
    fields['bundle_sha256']=hashlib.sha256(b'main-prompt-bundle-v2\0'+json.dumps(fields,ensure_ascii=False,allow_nan=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
    try:TypeAdapter(PromptProvenance).validate_python(fields)
    except ValidationError:pass
    else:raise AssertionError('zero selected component accepted')
    for damaged in ('different_base','aggregate','metadata'):
        try:
            if damaged=='different_base':assemble_main('custom',[],builtin_content=False,stock=select_template('intake'))
            elif damaged=='aggregate':assemble_main(SYSTEM_PROMPT,[],builtin_content=True,guidance=('plan','x'*65536),stock=select_template('intake'))
            else:assemble_main(SYSTEM_PROMPT,[ToolSpec(f't{i:03}-'+'x'*123,'Read',{}) for i in range(128)],builtin_content=True,stock=select_template('intake'))
        except ValueError:pass
        else:raise AssertionError(damaged+' accepted')
    return {'coherent_zero_stock_refused':True,'different_custom_aggregate_metadata_refused':True}

async def main():
    result={'compatibility':v1(),'retained_shape':shape(),'actual_calls':[]}
    with tempfile.TemporaryDirectory(prefix='stock-prompts-independent-') as temporary:
        for template in TEMPLATE_IDS:result['actual_calls'].append(await actual(template,False,Path(temporary)/template))
        result['actual_calls'].append(await actual('experiment',True,Path(temporary)/'planning'))
